#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include "texture.h"

int texture_width = 64;
int texture_height = 64;

uint32_t* mesh_texture = NULL;

bool load_png_texture_data(const char* filename){
    // It is a CPU renderer so we use IMG_Load to load the image as a buffer to the CPU
    // It would be more efficent to load to the texture to the GPU using IMG_LoadTexture(SDL_Renderer, const char* filename );
    SDL_Surface* image = IMG_Load(filename);

    if(image == NULL){
        fprintf(stderr, "failed to load texture: %s", SDL_GetError());
        return false;
    }

    image = SDL_ConvertSurfaceFormat(image, SDL_PIXELFORMAT_ARGB8888, 0);

    mesh_texture = (Uint32 *)image->pixels;
    texture_width = image->w;
    texture_height = image->h;

    SDL_free(image);

    return true;
    
}

tex2_t tex2_clone(tex2_t* t){
    tex2_t result = { t->u, t->v };
    return result;
}

